command:
/**
 * DarkSpace Cantina Generator
 * Assembles a random dive bar, cantina, or orbital lounge with unique atmospheric quirks.
 */
const pack = game.packs.get("darkspace.rollable-tables");
if (!pack) {
  ui.notifications.error("DarkSpace rollable-tables pack not found.");
} else {
  const adjTable = await pack.getDocument("dsTabCantNameAdj");
  const nounTable = await pack.getDocument("dsTabCantNameNn");
  const quirkTable = await pack.getDocument("dsTabCantinaQrk");

  const adj = (await adjTable?.draw({ displayChat: false }))?.results[0]?.text || "The Rusting";
  const noun = (await nounTable?.draw({ displayChat: false }))?.results[0]?.text || "Nebula";
  const quirk = (await quirkTable?.draw({ displayChat: false }))?.results[0]?.text || "Neon signs buzzing in the smoke.";

  const content = `
    <div style="border: 1px solid #ff7043; background: rgba(30, 15, 10, 0.95); color: #fbe9e7; padding: 12px; border-radius: 6px;">
      <h3 style="margin: 0 0 8px 0; color: #ffab91; border-bottom: 1px solid #ff7043; padding-bottom: 4px;">
        <i class="fas fa-cocktail"></i> ${adj} ${noun}
      </h3>
      <p style="margin: 6px 0;"><b>Atmosphere & Quirk:</b> ${quirk}</p>
    </div>
  `;

  await ChatMessage.create({
    user: game.user._id,
    speaker: { alias: "Frontier Guide" },
    content: content
  });
}
